import { GoogleGenAI, Type } from "@google/genai";
import { DigestData, GeneratedContentPack, NewsItem } from "../types";

// Инициализация API согласно правилам
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const getCurrentDate = () => {
  return new Date().toLocaleDateString('ru-RU', { day: 'numeric', month: 'long', year: 'numeric' });
};

/**
 * Поиск новостей с жесткой фильтрацией по дате (последние 48 часов)
 */
export const fetchRealNews = async (count: number = 10): Promise<DigestData> => {
  const model = "gemini-3-flash-preview"; 
  const today = getCurrentDate();

  const systemInstruction = `
    ТЫ — ВЕДУЩИЙ НОВОСТНИК "ПЕРВОГО ТУРИСТИЧЕСКОГО ТЕЛЕКАНАЛА". 
    ТЕКУЩАЯ ДАТА: ${today}.

    ЗАДАЧА: Найти ${count} ГОРЯЧИХ новостей мирового туризма, опубликованных СТРОГО за последние 48 часов (не ранее ${new Date(Date.now() - 48 * 3600000).toLocaleDateString('ru-RU')}). 
    Игнорируй старые статьи (2024, 2023 гг.), даже если они в топе поиска. Проверяй дату публикации в источнике!

    ФОРМАТ ОБЪЕКТА НОВОСТИ (news):
    - date: Реальная дата публикации из статьи.
    - sourceUrl: Прямая ссылка.
    - location: Страна/Город.

    ЖЕСТКИЕ ПРАВИЛА ОФОРМЛЕНИЯ ТЕКСТА:
    1. formattedDigestText (Дайджест):
       - Формат: "[ЭМОДЗИ] Заголовок — Краткая суть (1-2 предложения)".
       - Эмодзи должен соответствовать теме (✈️ для авиа, 🏨 для отелей, 🏔️ для гор и т.д.).
       - КАТЕГОРИЧЕСКИ ЗАПРЕЩЕНО писать ссылки и "Источник: ..." в этом поле.

    2. formattedShortDigest (Бегущая строка):
       - Формат: "[ЭМОДЗИ] Заголовок: Суть новости в 5 словах... "

    ТРЕБОВАНИЕ К КОЛЛАЖУ (collagePrompt):
    - Фотореалистичный промпт для обложки с надписью "НОВОСТИ ТУРИЗМА ${today}".
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Найди новости туризма за последние 48 часов (сегодня ${today}). Никаких новостей из прошлого года! Сгруппируй в дайджест с эмодзи.`,
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            news: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  summary: { type: Type.STRING },
                  ticker: { type: Type.STRING },
                  date: { type: Type.STRING },
                  location: { type: Type.STRING },
                  sourceUrl: { type: Type.STRING }
                },
                required: ["title", "summary", "ticker", "sourceUrl", "date"]
              }
            },
            formattedDigestText: { type: Type.STRING },
            formattedShortDigest: { type: Type.STRING },
            collagePrompt: { type: Type.STRING }
          },
          required: ["news", "formattedDigestText", "formattedShortDigest", "collagePrompt"]
        }
      }
    });

    const data = JSON.parse(response.text || "{}");
    data.news = data.news.map((n: any, i: number) => ({
      ...n, 
      id: `news-${Date.now()}-${i}`
    }));
    return data;
  } catch (error: any) {
    console.error("News Fetch Error:", error);
    throw new Error(`Ошибка поиска: ${error.message}`);
  }
};

/**
 * Генерация фотореалистичного изображения
 */
export const generateImageWithFeedback = async (prompt: string): Promise<{ data?: string, error?: string }> => {
  try {
    const photographyKeywords = "Extreme photorealism, shot on 35mm lens, high detail, professional lighting, NO ILLUSTRATION, NO CARTOON, 8k resolution.";
    const finalPrompt = `${prompt}. ${photographyKeywords}`;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: finalPrompt }] },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });

    const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (part?.inlineData?.data) {
      return { data: `data:image/png;base64,${part.inlineData.data}` };
    }
    return { error: "Не удалось получить изображение" };
  } catch (error: any) {
    return { error: error.message };
  }
};

export const generateArticleLongread = async (newsItem: NewsItem): Promise<Omit<GeneratedContentPack, 'generatedImages'>> => {
  const model = "gemini-3-pro-preview";
  const systemInstruction = `
    ТЫ — ГЛАВНЫЙ АВТОР "ПЕРВОГО ТУРИСТИЧЕСКОГО". 
    ТВОЙ СТИЛЬ: Блестящая ирония, тонкий сарказм и глубокий аналитический ум в духе Михаила Жванецкого или Иоанны Хмелевской. Это должно быть полноценное литературное эссе, а не сухой пересказ. Используй характерные речевые обороты, парадоксальные выводы и острые жизненные наблюдения.

    ОБЪЕМ: Минимум 3000 (ТРИ ТЫСЯЧИ) знаков. Текст должен быть развернутым, обстоятельным и захватывающим.

    ОБЯЗАТЕЛЬНАЯ ФАКТУРА: 
    - Используй ВСЕ цифры, цены, маршруты и названия из новости: ${newsItem.summary}. 
    - Добавь цитаты (можно стилизованные "под очевидцев" или "экспертов"), сравнения и исторические параллели.

    СТРУКТУРА СТАТЬИ (siteArticle):
    - Headline: Ироничный, бьющий в цель заголовок.
    - Sections: Минимум 5-6 секций (Заголовок + Текст с фактами, цифрами и иронией).
    - Hashtags (hashtags): В конце, ТОЛЬКО СЛОВА ЧЕРЕЗ ЗАПЯТУЮ, КАТЕГОРИЧЕСКИ БЕЗ СИМВОЛА #. Пример: туризм, отдых, сочи, цены.

    СОЦСЕТИ (socials):
    - Текст поста должен передавать СУТЬ новости с фактами и иронией.
    - Hashtags в соцсетях: С СИМВОЛОМ #.

    ВИЗУАЛИЗАЦИЯ (imagePrompts):
    - Ровно 3 (ТРИ) промпта для фотореалистичных иллюстраций объектов новости.
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Напиши большой лонгрид (минимум 3000 знаков) в стиле Жванецкого/Хмелевской по новости: ${newsItem.title}. Факты для использования: ${newsItem.summary}`,
      config: { 
        systemInstruction, 
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            siteArticle: {
              type: Type.OBJECT,
              properties: {
                headline: { type: Type.STRING },
                sections: {
                  type: Type.ARRAY,
                  items: {
                    type: Type.OBJECT,
                    properties: { heading: { type: Type.STRING }, body: { type: Type.STRING } },
                    required: ["heading", "body"]
                  }
                },
                hashtags: { type: Type.STRING }
              }
            },
            socials: {
              type: Type.OBJECT,
              properties: { tg: { type: Type.STRING }, vk_ok: { type: Type.STRING } }
            },
            imagePrompts: { type: Type.ARRAY, items: { type: Type.STRING } },
            metaDescription: { type: Type.STRING }
          },
          required: ["siteArticle", "socials", "imagePrompts", "metaDescription"]
        }
      }
    });
    return JSON.parse(response.text || "{}");
  } catch (error) {
    throw new Error("Ошибка генерации контента.");
  }
};

export const generateImagesForArticle = async (prompts: string[]): Promise<string[]> => {
  const images: string[] = [];
  const targetPrompts = prompts.slice(0, 3);
  for (const p of targetPrompts) {
    const res = await generateImageWithFeedback(p);
    if (res.data) images.push(res.data);
    await new Promise(r => setTimeout(r, 1000)); 
  }
  return images;
};

import React, { useState, useEffect } from 'react';
import { GeneratedContentPack, PublishingConfig, ArticleSection } from '../types';
import { publishToSmmBox, publishToWordPress } from '../services/publishingService';

interface ResultViewerProps {
  pack: GeneratedContentPack;
  pubConfig: PublishingConfig;
}

export const ResultViewer: React.FC<ResultViewerProps> = ({ pack, pubConfig }) => {
  const [activeTab, setActiveTab] = useState<'site' | 'tg' | 'vk_ok' | 'prompts'>('site');
  const [isEditing, setIsEditing] = useState(false);

  const [headline, setHeadline] = useState(pack.siteArticle?.headline || '');
  const [sections, setSections] = useState<ArticleSection[]>(pack.siteArticle?.sections || []);
  const [hashtags, setHashtags] = useState(pack.siteArticle?.hashtags || '');
  const [tgText, setTgText] = useState(pack.socials?.tg || '');
  const [vkOkText, setVkOkText] = useState(pack.socials?.vk_ok || '');

  const [pubStatus, setPubStatus] = useState<{ loading: boolean, success?: boolean, msg: string }>({ loading: false, msg: '' });

  const handleUpdateSection = (index: number, field: 'heading' | 'body', value: string) => {
    const newSections = [...sections];
    newSections[index] = { ...newSections[index], [field]: value };
    setSections(newSections);
  };

  const handlePublishWP = async () => {
    setPubStatus({ loading: true, msg: 'Публикация на сайт...' });
    try {
      await publishToWordPress(
        pubConfig.wordPress,
        pubConfig.useProxy,
        headline,
        sections,
        pack.generatedImages,
        hashtags,
        pack.metaDescription,
        undefined,
        (msg) => setPubStatus({ loading: true, msg })
      );
      setPubStatus({ loading: false, success: true, msg: 'Статья опубликована на WordPress!' });
    } catch (e: any) {
      setPubStatus({ loading: false, success: false, msg: `Ошибка WP: ${e.message}` });
    }
  };

  const handlePublishSmmBox = async (text: string) => {
    setPubStatus({ loading: true, msg: 'Отправка в соцсети...' });
    try {
      await publishToSmmBox(pubConfig, text, pack.generatedImages);
      setPubStatus({ loading: false, success: true, msg: 'Пост запланирован в SmmBox!' });
    } catch (e: any) {
      setPubStatus({ loading: false, success: false, msg: `Ошибка SmmBox: ${e.message}` });
    }
  };

  return (
    <div className="bg-white rounded-[2.5rem] shadow-2xl border border-slate-50 overflow-hidden animate-fade-in mb-10">
      {/* Header */}
      <div className="bg-brand-dark p-8 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div className="flex flex-col">
          <span className="text-brand-orange text-[10px] font-black uppercase tracking-[0.2em] mb-1">Готовый материал</span>
          <h3 className="text-white font-black text-xl italic leading-tight uppercase line-clamp-1">{headline}</h3>
        </div>
        <div className="flex gap-2">
           <button 
             onClick={() => setIsEditing(!isEditing)} 
             className={`px-6 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${isEditing ? 'bg-brand-orange text-white' : 'bg-white/10 text-white hover:bg-white/20'}`}
           >
             {isEditing ? '💾 Сохранить' : '📝 Править'}
           </button>
           <button 
             onClick={handlePublishWP}
             disabled={pubStatus.loading}
             className="px-6 py-3 bg-brand-orange text-white rounded-xl text-[10px] font-black uppercase hover:scale-105 transition-all shadow-lg shadow-orange-900/20 disabled:opacity-50"
           >
             {pubStatus.loading && activeTab === 'site' ? '⌛...' : '🌐 На сайт'}
           </button>
        </div>
      </div>

      {/* Tabs Navigation */}
      <div className="flex border-b border-slate-100 bg-slate-50/50 p-2">
        {(['site', 'tg', 'vk_ok', 'prompts'] as const).map(tab => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className={`flex-1 py-3 text-[10px] font-black uppercase tracking-wider rounded-xl transition-all ${activeTab === tab ? 'bg-white text-brand-dark shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
          >
            {tab === 'site' ? 'Статья' : tab === 'tg' ? 'Telegram' : tab === 'vk_ok' ? 'VK/OK' : 'Промпты'}
          </button>
        ))}
      </div>

      {/* Feedback Bar */}
      {pubStatus.msg && (
        <div className={`px-8 py-3 text-[10px] font-bold text-center uppercase tracking-widest animate-fade-in ${pubStatus.success ? 'bg-green-50 text-green-600' : pubStatus.success === false ? 'bg-red-50 text-red-600' : 'bg-orange-50 text-brand-orange'}`}>
          {pubStatus.msg}
        </div>
      )}

      {/* Content Area */}
      <div className="p-8">
        {activeTab === 'site' && (
          <div className="max-w-3xl mx-auto space-y-8">
            {isEditing ? (
              <input 
                value={headline} 
                onChange={e => setHeadline(e.target.value)}
                className="w-full text-4xl font-black italic text-brand-dark border-b-2 border-brand-orange/20 focus:border-brand-orange outline-none pb-2 bg-transparent"
              />
            ) : (
              <h1 className="text-4xl font-black italic text-brand-dark leading-tight">{headline}</h1>
            )}

            {/* Images Gallery */}
            <div className="grid grid-cols-3 gap-4">
               {pack.generatedImages.map((img, i) => (
                 <div key={i} className="aspect-video bg-slate-100 rounded-2xl overflow-hidden border border-slate-100 shadow-sm group relative">
                    <img src={img} className="w-full h-full object-cover" alt="Gen" />
                    <div className="absolute inset-0 bg-brand-dark/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                        <span className="text-[8px] text-white font-black uppercase">Иллюстрация {i+1}</span>
                    </div>
                 </div>
               ))}
            </div>

            <div className="article-font space-y-6 text-lg text-slate-700 leading-[1.8] antialiased">
              {sections.map((sec, idx) => (
                <div key={idx} className="space-y-4">
                  {isEditing ? (
                    <>
                      <input 
                        value={sec.heading} 
                        onChange={e => handleUpdateSection(idx, 'heading', e.target.value)}
                        className="w-full font-bold text-xl text-brand-dark border-l-4 border-brand-orange pl-4 outline-none bg-slate-50 py-2 rounded-r-lg"
                      />
                      <textarea 
                        value={sec.body} 
                        onChange={e => handleUpdateSection(idx, 'body', e.target.value)}
                        rows={6}
                        className="w-full p-4 border border-slate-200 rounded-2xl outline-none focus:ring-2 focus:ring-brand-orange/20 text-base"
                      />
                    </>
                  ) : (
                    <>
                      <h2 className="text-2xl font-bold text-brand-dark border-l-4 border-brand-orange pl-6 my-8">{sec.heading}</h2>
                      <div className="whitespace-pre-wrap">{sec.body}</div>
                    </>
                  )}
                </div>
              ))}
            </div>

            <div className="pt-10 border-t border-slate-100">
               <span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em] mb-4 block">Теги материала</span>
               {isEditing ? (
                 <input 
                   value={hashtags} 
                   onChange={e => setHashtags(e.target.value)}
                   className="w-full p-4 bg-slate-50 border border-slate-100 rounded-xl text-xs font-bold text-brand-orange outline-none"
                 />
               ) : (
                 <div className="flex flex-wrap gap-2">
                    {hashtags.split(',').map((t, i) => (
                      <span key={i} className="px-3 py-1.5 bg-orange-50 text-brand-orange text-[10px] font-black uppercase rounded-lg border border-orange-100">#{t.trim()}</span>
                    ))}
                 </div>
               )}
            </div>
          </div>
        )}

        {activeTab === 'tg' && (
          <div className="max-w-2xl mx-auto space-y-6">
             <div className="bg-slate-50 p-8 rounded-[2rem] border border-slate-100 relative">
                <span className="absolute -top-3 left-8 bg-brand-dark text-white px-4 py-1 rounded-full text-[8px] font-black uppercase tracking-widest">Post Preview</span>
                <textarea 
                  value={tgText} 
                  onChange={e => setTgText(e.target.value)}
                  readOnly={!isEditing}
                  rows={12}
                  className="w-full bg-transparent outline-none text-slate-800 text-sm leading-relaxed resize-none font-medium"
                />
             </div>
             <button 
               onClick={() => handlePublishSmmBox(tgText)}
               disabled={pubStatus.loading}
               className="w-full py-5 bg-[#0088cc] text-white rounded-2xl font-black uppercase text-xs tracking-widest shadow-xl shadow-blue-100 hover:scale-[1.02] transition-all disabled:opacity-50"
             >
               🚀 Опубликовать в Telegram (через SmmBox)
             </button>
          </div>
        )}

        {activeTab === 'vk_ok' && (
          <div className="max-w-2xl mx-auto space-y-6">
             <div className="bg-slate-50 p-8 rounded-[2rem] border border-slate-100 relative">
                <span className="absolute -top-3 left-8 bg-[#4c75a3] text-white px-4 py-1 rounded-full text-[8px] font-black uppercase tracking-widest">VK / OK Content</span>
                <textarea 
                  value={vkOkText} 
                  onChange={e => setVkOkText(e.target.value)}
                  readOnly={!isEditing}
                  rows={12}
                  className="w-full bg-transparent outline-none text-slate-800 text-sm leading-relaxed resize-none font-medium"
                />
             </div>
             <button 
               onClick={() => handlePublishSmmBox(vkOkText)}
               disabled={pubStatus.loading}
               className="w-full py-5 bg-[#4c75a3] text-white rounded-2xl font-black uppercase text-xs tracking-widest shadow-xl shadow-blue-100 hover:scale-[1.02] transition-all disabled:opacity-50"
             >
               🚀 Опубликовать в VK/OK (через SmmBox)
             </button>
          </div>
        )}

        {activeTab === 'prompts' && (
          <div className="max-w-3xl mx-auto grid grid-cols-1 md:grid-cols-2 gap-6">
             {pack.imagePrompts.map((p, i) => (
               <div key={i} className="bg-slate-50 p-6 rounded-3xl border border-slate-100 group">
                  <div className="flex justify-between items-center mb-4">
                    <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Prompt {i+1}</span>
                    <button onClick={() => navigator.clipboard.writeText(p)} className="text-brand-orange font-black text-[9px] uppercase hover:underline">Copy 📋</button>
                  </div>
                  <p className="text-[11px] text-slate-600 italic leading-relaxed group-hover:text-brand-dark transition-colors">"{p}"</p>
               </div>
             ))}
             <div className="bg-brand-dark/5 p-6 rounded-3xl border border-brand-dark/10 md:col-span-2">
                <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest block mb-2">Meta Description (SEO)</span>
                <p className="text-xs font-bold text-slate-700">{pack.metaDescription}</p>
             </div>
          </div>
        )}
      </div>
    </div>
  );
};

