import { PublishingConfig, WordPressConfig } from "../types";

const SMMBOX_BASE_URL = "https://smmbox.com/api/v1";

/**
 * Вспомогательная функция для форматирования даты под WordPress
 * Преобразует в формат YYYY-MM-DDTHH:MM:SS
 */
const formatDateForWP = (dateStr: string) => {
    if (!dateStr) return null;
    const date = new Date(dateStr);
    // Мы возвращаем строку ISO без миллисекунд и суффикса Z, 
    // чтобы WordPress воспринял это как локальное время сайта
    return date.toISOString().split('.')[0]; 
};

/**
 * Оборачивает URL в CORS прокси. 
 */
const wrapUrl = (url: string, useProxy: boolean) => {
    if (!useProxy) return url;
    return `https://corsproxy.io/?${encodeURIComponent(url)}`;
};

const fetchWithTimeout = async (url: string, options: RequestInit = {}, useProxy: boolean = false, timeout = 90000) => {
    const finalUrl = wrapUrl(url, useProxy);
    const controller = new AbortController();
    const id = setTimeout(() => controller.abort(), timeout);

    try {
        const response = await fetch(finalUrl, { 
            ...options, 
            signal: controller.signal
        });
        clearTimeout(id);

        if (response.status === 401) {
            throw new Error("401 Unauthorized: Проверьте API Токен в настройках.");
        }

        if (!response.ok) {
            const errText = await response.text();
            let errorMessage = `Ошибка ${response.status}`;
            try {
                const errData = JSON.parse(errText);
                errorMessage = errData.message || errData.error?.message || errorMessage;
            } catch (e) {
                if (errText.includes("<!DOCTYPE")) errorMessage += " (Сервер вернул HTML вместо JSON)";
                else errorMessage += `: ${errText.slice(0, 100)}`;
            }
            throw new Error(errorMessage);
        }

        return response;
    } catch (error: any) {
        clearTimeout(id);
        if (error.name === 'AbortError') throw new Error("Превышено время ожидания (таймаут).");
        if (error.message === 'Failed to fetch') {
            throw new Error("Ошибка сети (CORS). Попробуйте переключить 'Использовать Прокси' в настройках.");
        }
        throw error;
    }
};

/**
 * Получение групп SmmBox
 */
export const fetchSmmBoxGroups = async (config: PublishingConfig) => {
    const url = `${SMMBOX_BASE_URL}/groups`;
    const response = await fetchWithTimeout(url, {
        method: 'GET',
        headers: { 
            'Accept': 'application/json',
            'Authorization': `Bearer ${config.smmBoxToken}`
        }
    }, config.useProxy);

    const data = await response.json();
    return data.response || [];
};

/**
 * Публикация в SmmBox
 */
export const publishToSmmBox = async (
    config: PublishingConfig, 
    text: string, 
    imagesBase64: string[] = [], 
    publishDate?: Date
) => {
    if (!config.smmBoxToken) throw new Error("SmmBox Token не настроен");

    const allGroups = await fetchSmmBoxGroups(config);
    const targetGroups = allGroups.filter((g: any) => 
        g.name.toLowerCase().includes(config.targetGroupName.toLowerCase())
    );

    if (targetGroups.length === 0) {
        throw new Error(`Проект/Группа "${config.targetGroupName}" не найдена. Проверьте название точно как в SmmBox.`);
    }

    const attachments: any[] = [{ type: 'text', text }];

    // Ограничиваем до 3 для соцсетей
    imagesBase64.filter(img => img && img.startsWith('data:')).slice(0, 3).forEach(img => {
        attachments.push({ type: 'photo', original: img });
    });

    // Если дата не передана, ставим +10 минут от текущего времени
    const postTime = publishDate || new Date(Date.now() + 10 * 60000);
    const unixTimestamp = Math.floor(postTime.getTime() / 1000);

    const postsData = targetGroups.map((group: any) => ({
        group: { id: group.id, social: group.social, type: group.type },
        date: unixTimestamp,
        attachments: attachments,
        options: ['from_group']
    }));

    const url = `${SMMBOX_BASE_URL}/posts/postpone`;
    const response = await fetchWithTimeout(url, {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${config.smmBoxToken}`
        },
        body: JSON.stringify({ posts: postsData })
    }, config.useProxy);

    const result = await response.json();
    return result;
};

/**
 * Загрузка медиа в WordPress
 */
const uploadMediaToWP = async (wpConfig: WordPressConfig, useProxy: boolean, base64: string, filename: string) => {
    const res = await fetch(base64);
    const blob = await res.blob();
    const formData = new FormData();
    formData.append('file', blob, filename);

    const auth = btoa(`${wpConfig.username}:${wpConfig.applicationPassword}`);
    const url = `${wpConfig.url.replace(/\/$/, '')}/wp-json/wp/v2/media`;

    const response = await fetchWithTimeout(url, {
        method: 'POST',
        headers: { 'Authorization': `Basic ${auth}` },
        body: formData
    }, useProxy);

    return await response.json();
};

/**
 * WordPress Публикация
 */
export const publishToWordPress = async (
    config: WordPressConfig, 
    useProxy: boolean,
    title: string, 
    sections: {heading: string, body: string}[], 
    imagesBase64: string[], 
    tags: string,
    metaDescription: string,
    publishDateStr?: string,
    onProgress?: (msg: string) => void
) => {
    if (!config.url || !config.applicationPassword) throw new Error("Настройки WordPress не заполнены");

    const uploadedMediaUrls: string[] = [];
    // ТРЕБОВАНИЕ: Теперь грузим 3 картинки в WordPress
    const validImages = imagesBase64.filter(img => img && img.length > 100).slice(0, 3);

    for (let i = 0; i < validImages.length; i++) {
        try {
            if (onProgress) onProgress(`Загрузка фото ${i + 1} из ${validImages.length}...`);
            const media = await uploadMediaToWP(config, useProxy, validImages[i], `tourgenius-${Date.now()}-${i}.png`);
            uploadedMediaUrls.push(media.source_url);
        } catch (e) {
            console.warn("Ошибка загрузки фото в WP", e);
        }
    }

    let htmlContent = '';
    sections.forEach((s, idx) => {
        if (s.heading) htmlContent += `<h2 class="wp-block-heading"><strong>${s.heading}</strong></h2>`;

        const paragraphs = s.body.split('\n').filter(p => p.trim());
        paragraphs.forEach(p => {
            htmlContent += `<p>${p.trim()}</p>`;
        });

        // Распределяем картинки между секциями: 1-я после 1-й, 2-я после 2-й, 3-я после 3-й
        if (uploadedMediaUrls[idx]) {
            htmlContent += `<figure class="wp-block-image size-large"><img src="${uploadedMediaUrls[idx]}" alt="${title}" /></figure>`;
        }
    });

    if (tags) {
        htmlContent += `<hr /><p><strong>Теги:</strong> ${tags}</p>`;
    }

    if (onProgress) onProgress(`Создание записи...`);

    const auth = btoa(`${config.username}:${config.applicationPassword}`);
    const url = `${config.url.replace(/\/$/, '')}/wp-json/wp/v2/posts`;

    const wpDate = formatDateForWP(publishDateStr || "");

    const body: any = {
        title: title,
        content: htmlContent,
        status: wpDate ? 'future' : 'publish',
        excerpt: metaDescription
    };

    if (wpDate) {
        body.date = wpDate; // WordPress использует локальное время сайта
    }

    const response = await fetchWithTimeout(url, {
        method: 'POST',
        headers: {
            'Authorization': `Basic ${auth}`,
            'Content-Type': 'application/json'
        },
        body: JSON.stringify(body)
    }, useProxy);

    return await response.json();
};

