  const [vkOkText, setVkOkText] = useState(pack.socials?.vk_ok || '');
  const [scheduleDate, setScheduleDate] = useState<string>('');

  const [pubStatus, setPubStatus] = useState<{ loading: boolean, success?: boolean, msg: string }>({ loading: false, msg: '' });

  const handleUpdateSection = (index: number, field: 'heading' | 'body', value: string) => {
    const newSections = [...sections];
    newSections[index] = { ...newSections[index], [field]: value };
    setSections(newSections);
  };

  const handlePublishWP = async () => {
    setPubStatus({ loading: true, msg: 'Публикация на сайт...' });
    try {
      await publishToWordPress(
        pubConfig.wordPress,
        pubConfig.useProxy,
        headline,
        sections,
        pack.generatedImages,
        hashtags,
        pack.metaDescription,
        scheduleDate,
        (msg) => setPubStatus({ loading: true, msg })
      );
      setPubStatus({ 
        loading: false, 
        success: true, 
        msg: scheduleDate ? `Статья запланирована на ${new Date(scheduleDate).toLocaleString('ru-RU')}!` : 'Статья опубликована на WordPress!' 
      });
    } catch (e: any) {
      setPubStatus({ loading: false, success: false, msg: `Ошибка WP: ${e.message}` });
    }
  };

  const handlePublishSmmBox = async (text: string) => {
    setPubStatus({ loading: true, msg: 'Отправка в соцсети...' });
    try {
      await publishToSmmBox(pubConfig, text, pack.generatedImages, scheduleDate ? new Date(scheduleDate) : undefined);
      setPubStatus({ 
        loading: false, 
        success: true, 
        msg: scheduleDate ? `Пост запланирован на ${new Date(scheduleDate).toLocaleString('ru-RU')}!` : 'Пост запланирован в SmmBox!' 
      });
    } catch (e: any) {
      setPubStatus({ loading: false, success: false, msg: `Ошибка SmmBox: ${e.message}` });
    }
  };

  return (
    <div className="bg-white rounded-[2.5rem] shadow-2xl border border-slate-50 overflow-hidden animate-fade-in mb-10">
      <div className="bg-brand-dark p-8 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
