        </div>
      </div>

      <div className="flex border-b border-slate-100 bg-slate-50/50 p-2">
        {(['site', 'tg', 'vk_ok', 'prompts'] as const).map(tab => (
          <button key={tab} onClick={() => setActiveTab(tab)} className={`flex-1 py-3 text-[10px] font-black uppercase tracking-wider rounded-xl transition-all ${activeTab === tab ? 'bg-white text-brand-dark shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>
            {tab === 'site' ? 'Статья' : tab === 'tg' ? 'Telegram' : tab === 'vk_ok' ? 'VK/OK' : 'Промпты'}
          </button>
        ))}
      </div>

      <div className="px-8 py-4 bg-slate-50/30 border-b border-slate-100 flex items-center gap-4">
        <div className="flex flex-col gap-1 flex-1 max-w-xs">
          <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Дата публикации (МСК)</label>
          <input type="datetime-local" value={scheduleDate} onChange={e => setScheduleDate(e.target.value)} className="text-xs p-2.5 rounded-xl border border-slate-200 outline-none bg-white font-bold text-brand-dark focus:ring-2 focus:ring-brand-orange transition-all" />
        </div>
        {scheduleDate && <button onClick={() => setScheduleDate('')} className="text-[10px] font-black text-slate-300 uppercase hover:text-red-500 transition-colors">Сбросить дату ✖</button>}
      </div>

      {pubStatus.msg && <div className={`px-8 py-3 text-[10px] font-bold text-center uppercase tracking-widest animate-fade-in ${pubStatus.success ? 'bg-green-50 text-green-600' : pubStatus.success === false ? 'bg-red-50 text-red-600' : 'bg-orange-50 text-brand-orange'}`}>{pubStatus.msg}</div>}

