import { GoogleGenAI, Type } from "@google/genai";
import { DigestData, GeneratedContentPack, NewsItem } from "../types";

// Инициализация API согласно правилам
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const getCurrentDate = () => {
  return new Date().toLocaleDateString('ru-RU', { day: 'numeric', month: 'long', year: 'numeric' });
};

/**
 * Поиск новостей с жесткой фильтрацией по дате (последние 48 часов)
 * С фокусом на связи с Россией или россиянами
 */
export const fetchRealNews = async (count: number = 12): Promise<DigestData> => {
  const model = "gemini-3-flash-preview"; 
  const today = getCurrentDate();
  const cutoffTime = Date.now() - 48 * 3600000;
  const cutoffDate = new Date(cutoffTime).toLocaleDateString('ru-RU');

  const systemInstruction = `
    ТЫ — ВЕДУЩИЙ НОВОСТНИК "ПЕРВОГО ТУРИСТИЧЕСКОГО ТЕЛЕКАНАЛА". 
    ТЕКУЩАЯ ДАТА: ${today}.

    ЗАДАЧА: Найти ${count} ГОРЯЧИХ новостей мирового туризма, СВЯЗАННЫХ С РОССИЕЙ ИЛИ РОССИЯНАМИ ПРЯМО ИЛИ КОСВЕННО, опубликованных СТРОГО за последние 48 часов (после ${cutoffDate}). 

    ЖЕСТКИЕ ПРАВИЛА ФИЛЬТРАЦИИ:
    1. КАТЕГОРИЧЕСКИ ЗАПРЕЩЕНО использовать новости старше 48 часов. Если новость опубликована более 2 дней назад — она не подходит.
    2. Игнорируй любые результаты из 2024 года и ранее.
    3. Проверяй даты в URL и метаданных. Только свежая повестка (визы, рейсы, инциденты, новые правила).

    ФОРМАТ ОБЪЕКТА НОВОСТИ (news):
    - date: Реальная дата публикации.
    - sourceUrl: Прямая ссылка.
    - location: Страна/Город.

    ЖЕСТКИЕ ПРАВИЛА ОФОРМЛЕНИЯ ТЕКСТА:
    1. formattedDigestText (Дайджест):
       - Формат: "[ЭМОДЗИ] Заголовок — Краткая суть (1-2 предложения)".

    2. formattedShortDigest (Бегущая строка):
       - ФОРМАТ: "[ЭМОДЗИ] Новость: Краткое пояснение сути".

    ТРЕБОВАНИЕ К КОЛЛАЖУ (collagePrompt):
    - Фотореалистичный промпт для обложки с надписью "НОВОСТИ ТУРИЗМА".
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Найди 12 самых актуальных новостей туризма (РФ и мир для россиян), опубликованных строго за последние 48 часов (после ${cutoffDate}).`,
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            news: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  summary: { type: Type.STRING },
                  ticker: { type: Type.STRING },
                  date: { type: Type.STRING },
                  location: { type: Type.STRING },
                  sourceUrl: { type: Type.STRING }
                },
                required: ["title", "summary", "ticker", "sourceUrl", "date"]
              }
            },
            formattedDigestText: { type: Type.STRING },
            formattedShortDigest: { type: Type.STRING },
            collagePrompt: { type: Type.STRING }
          },
          required: ["news", "formattedDigestText", "formattedShortDigest", "collagePrompt"]
        }
      }
    });

    const data = JSON.parse(response.text || "{}");
    data.news = data.news.map((n: any, i: number) => ({
      ...n, 
      id: `news-${Date.now()}-${i}`
    }));
    return data;
  } catch (error: any) {
    console.error("News Fetch Error:", error);
    throw new Error(`Ошибка поиска: ${error.message}`);
  }
};

export const generateImageWithFeedback = async (prompt: string): Promise<{ data?: string, error?: string }> => {
  try {
    const photographyKeywords = "Extreme photorealism, shot on 35mm lens, high detail, professional lighting, NO ILLUSTRATION, NO CARTOON, 8k resolution.";
    const finalPrompt = `${prompt}. ${photographyKeywords}`;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: finalPrompt }] },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });

    const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (part?.inlineData?.data) {
      return { data: `data:image/png;base64,${part.inlineData.data}` };
    }
    return { error: "Не удалось получить изображение" };
  } catch (error: any) {
    return { error: error.message };
  }
};

export const generateArticleLongread = async (newsItem: NewsItem): Promise<Omit<GeneratedContentPack, 'generatedImages'>> => {
  const model = "gemini-3-pro-preview";
  const systemInstruction = `
    ТЫ — ГЛАВНЫЙ АВТОР "ПЕРВОГО ТУРИСТИЧЕСКОГО". 
    ТВОЙ СТИЛЬ: Блестящая ирония, тонкий сарказм и глубокий аналитический ум в духе Михаила Жванецкого или Иоанны Хмелевской. Это полноценное литературное эссе (минимум 3000 знаков).

    КРИТИЧЕСКОЕ ТРЕБОВАНИЕ К ПОВЕСТВОВАНИЮ:
    Пиши СТРОГО ОТ ЛИЦА РЕДАКЦИИ ПЕРВОГО ТУРИСТИЧЕСКОГО (используй "мы", "наша редакция", "нам кажется", "редакция полагает"). 
    КАТЕГОРИЧЕСКИ ЗАПРЕЩЕНО использовать первое лицо единственного числа ("я", "мой", "мне"). Текст должен звучать как коллективное мнение авторитетного медиа.

    ДОПОЛНИТЕЛЬНАЯ ПОВЕДЕНЧЕСКАЯ И РЕДАКТОРСКАЯ ЗАДАЧА (РЕЖИССУРА ВНИМАНИЯ):
    Текст должен быть режиссирован как медийный маршрут. Цель — удержание 5-10 минут.

    1. ВСТУПЛЕНИЕ (Первая секция):
       - Обращайся к жизненному состоянию читателя от лица редакции. 
       - Обозначь, зачем читать дальше.
       - После вступления добавь "Карту маршрута": 2-4 смысловых ориентира человеческим языком.

    2. СВЯЗНОСТЬ И ПЕРЕХОДЫ:
       - Каждая секция логически вытекает из предыдущей.
       - Завершай секции "смысловым крючком" или вопросом.
       - Подзаголовки должны отвечать на внутренние вопросы читателя.

    3. ВНУТРЕННИЕ ПАУЗЫ:
       - Смена ритма, парадоксы, короткие наблюдения.

    4. ФИНАЛ (Последняя секция):
       - Блок "Продолжение разговора" или "Что читать дальше".
       - Обозначь 2-3 направления для развития мысли. Не ставь точку, оставь разговор открытым.

    ЧТО НЕ ДЕЛАТЬ:
    - Не упрощать язык, не снижать уровень, не превращать в гайд/инструкцию.
    - Никакого "Я". Только "Редакция" или "Мы".

    СТРУКТУРА:
    - Headline: Ироничный.
    - Sections: Минимум 6-7 (Включая Вступление и Финал).
    - Hashtags: Без символа # в поле tags, через запятую.
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Напиши аналитический лонгрид (3000+ знаков) от лица редакции с режиссурой внимания по новости: ${newsItem.title}. Факты: ${newsItem.summary}`,
      config: { 
        systemInstruction, 
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            siteArticle: {
              type: Type.OBJECT,
              properties: {
                headline: { type: Type.STRING },
                sections: {
                  type: Type.ARRAY,
                  items: {
                    type: Type.OBJECT,
                    properties: { heading: { type: Type.STRING }, body: { type: Type.STRING } },
                    required: ["heading", "body"]
                  }
                },
                hashtags: { type: Type.STRING }
              }
            },
            socials: {
              type: Type.OBJECT,
              properties: { tg: { type: Type.STRING }, vk_ok: { type: Type.STRING } }
            },
            imagePrompts: { type: Type.ARRAY, items: { type: Type.STRING } },
            metaDescription: { type: Type.STRING }
          },
          required: ["siteArticle", "socials", "imagePrompts", "metaDescription"]
        }
      }
    });
    return JSON.parse(response.text || "{}");
  } catch (error) {
    throw new Error("Ошибка генерации контента.");
  }
};

export const generateImagesForArticle = async (prompts: string[]): Promise<string[]> => {
  const images: string[] = [];
  const targetPrompts = prompts.slice(0, 3);
  for (const p of targetPrompts) {
    const res = await generateImageWithFeedback(p);
    if (res.data) images.push(res.data);
    await new Promise(r => setTimeout(r, 1000)); 
  }
  return images;
};

