export const fetchRealNews = async (count: number = 12): Promise<DigestData> => {
  const model = "gemini-3-flash-preview"; 
  const now = new Date();
  const todayStr = getCurrentDate();
  const cutoffTime = Date.now() - 48 * 3600000;
  const cutoffDateStr = new Date(cutoffTime).toLocaleDateString('ru-RU');

  const systemInstruction = `
    ТЫ — ВЕДУЩИЙ НОВОСТНИК "ПЕРВОГО ТУРИСТИЧЕСКОГО ТЕЛЕКАНАЛА". 
    СЕГОДНЯ: ${todayStr}.

    ЗАДАЧА: Найти ${count} ГОРЯЧИХ новостей туризма, опубликованных СТРОГО за последние 48 часов (после ${cutoffDateStr}).

    ЖЕСТКИЙ ФИЛЬТР ДАТ (ЗАЩИТА ОТ АНАХРОНИЗМОВ):
    1. ИГНОРИРУЙ ЛЮБЫЕ НОВОСТИ ЗА 2024 ГОД. Если в тексте новости есть "2024", "май 2024", "год назад" — это мусор, НЕ БЕРИ ЕГО.
    2. Пример ошибки: "Аэропорт Элисты принял первый рейс" — это новость от МАЯ 2024 года. НЕ ИСПОЛЬЗУЙ ЕЕ. 
    3. Проверяй дату публикации в каждом поисковом результате. Нам нужны только события СЕГОДНЯШНЕГО И ВЧЕРАШНЕГО ДНЯ.

    ВЕРИФИКАЦИЯ ССЫЛОК (ЗАЩИТА ОТ 404):
    1. Ты обязан использовать ТОЛЬКО те URL (sourceUrl), которые ПРЯМО указаны в метаданных поиска (grounding metadata).
    2. КАТЕГОРИЧЕСКИ ЗАПРЕЩЕНО изменять ссылки, сокращать их или придумывать свои.
    3. Ссылка должна быть полной (с https://) и вести на страницу КОНКРЕТНОЙ новости.
    4. Если ссылка кажется подозрительной (ведет на поиск или главную) — не бери эту новость.

    ФОРМАТ ОБЪЕКТА НОВОСТИ (news):
    - title: Короткий и хлёсткий заголовок.
    - summary: 2-3 предложения сути.
    - sourceUrl: Реальная, проверенная, живая ссылка.
    - date: Дата публикации в формате ДД.ММ.ГГГГ.

    ЖЕСТКИЕ ПРАВИЛА ОФОРМЛЕНИЯ ТЕКСТА:
    1. formattedDigestText (Дайджест): "[ЭМОДЗИ] Заголовок — Суть".
    2. formattedShortDigest (Бегущая строка): "[ЭМОДЗИ] Новость: Краткое пояснение".
    3. collagePrompt: Промпт для фотореалистичной обложки.
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      // Добавляем в промпт текущий год для усиления фильтрации
      contents: `Найди новости туризма РФ и мира за последние 48 часов (с ${cutoffDateStr} по ${todayStr}). Исключи любые результаты за 2024 год. Проверь, чтобы ссылки (sourceUrl) были рабочими и вели прямо на статьи.`,
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            news: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  summary: { type: Type.STRING },
                  ticker: { type: Type.STRING },
                  date: { type: Type.STRING },
                  location: { type: Type.STRING },
                  sourceUrl: { type: Type.STRING }
                },
                required: ["title", "summary", "ticker", "sourceUrl", "date"]
              }
            },
            formattedDigestText: { type: Type.STRING },
            formattedShortDigest: { type: Type.STRING },
            collagePrompt: { type: Type.STRING }
          },
          required: ["news", "formattedDigestText", "formattedShortDigest", "collagePrompt"]
        }
      }
    });

    const data = JSON.parse(response.text || "{}");
    // Дополнительная программная фильтрация на случай, если модель пропустила старую дату
    const filteredNews = (data.news || []).filter((n: any) => {
        const is2024 = n.date?.includes('2024') || n.title?.includes('2024') || n.summary?.includes('2024');
        return !is2024;
    });

    return {
        ...data,
        news: filteredNews.map((n: any, i: number) => ({
            ...n, 
            id: `news-${Date.now()}-${i}`
        }))
    };
  } catch (error: any) {
    console.error("News Fetch Error:", error);
    throw new Error(`Ошибка поиска новостей: ${error.message}`);
  }
};

export const generateImageWithFeedback = async (prompt: string): Promise<{ data?: string, error?: string }> => {
  try {
    const photographyKeywords = "Photorealistic, professional travel photography, 8k, highly detailed, no text on image except where specified.";
    const finalPrompt = `${prompt}. ${photographyKeywords}`;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: finalPrompt }] },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });

    const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (part?.inlineData?.data) {
      return { data: `data:image/png;base64,${part.inlineData.data}` };
    }
    return { error: "Не удалось получить изображение" };
  } catch (error: any) {
    return { error: error.message };
  }
};

