import { GoogleGenAI, Type } from "@google/genai";
import { DigestData, GeneratedContentPack, NewsItem } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const getCutoffDate = () => {
  const d = new Date(Date.now() - 48 * 3600000);
  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
};

export const fetchRealNews = async (count: number = 12): Promise<DigestData> => {
  const model = "gemini-3-flash-preview"; 
  const cutoff = getCutoffDate();
  const today = new Date().toLocaleDateString('ru-RU');

  const systemInstruction = `
    ТЫ — ГЛАВНЫЙ РЕДАКТОР "ПЕРВОГО ТУРИСТИЧЕСКОГО". 
    СЕГОДНЯ: ${today}.

    ЗАДАЧА: Найти новости туризма, опубликованные СТРОГО за последние 48 часов. 

    ПРАВИЛА:
    1. ИГНОРИРУЙ ВСЁ ЗА 2024 ГОД. Если в новости есть 2024 — это ошибка, не бери её.
    2. ПРОВЕРЯЙ ДАТУ ПЕРЕД ТЕМ КАК ВКЛЮЧИТЬ В СПИСОК.
    3. Для каждой новости ОБЯЗАТЕЛЬНА прямая рабочая ссылка (sourceUrl).
    4. Стиль дайджеста и бегущей строки сохраняй: иронично, коротко, с эмодзи.
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      // Используем оператор after: для принудительного ограничения поиска в Google
      contents: `Найди 12 актуальных новостей по запросу: "новости туризма Россия" after:${cutoff}. Исключи новости за 2024 год. Проверь ссылки.`,
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            news: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  summary: { type: Type.STRING },
                  ticker: { type: Type.STRING },
                  date: { type: Type.STRING },
                  location: { type: Type.STRING },
                  sourceUrl: { type: Type.STRING }
                },
                required: ["title", "summary", "ticker", "sourceUrl", "date"]
              }
            },
            formattedDigestText: { type: Type.STRING },
            formattedShortDigest: { type: Type.STRING },
            collagePrompt: { type: Type.STRING }
          },
          required: ["news", "formattedDigestText", "formattedShortDigest", "collagePrompt"]
        }
      }
    });

    const data = JSON.parse(response.text || "{}");
    // Дополнительная чистка от 2024 года в коде
    data.news = (data.news || []).filter((n: any) => !n.date?.includes('2024') && !n.title?.includes('2024'));

    return {
      ...data,
      news: data.news.map((n: any, i: number) => ({ ...n, id: `news-${Date.now()}-${i}` }))
    };
  } catch (error: any) {
    throw new Error(`Ошибка поиска: ${error.message}`);
  }
};

export const generateArticleLongread = async (newsItem: NewsItem): Promise<Omit<GeneratedContentPack, 'generatedImages'>> => {
