        const res = await fetch(base64);
        const blob = await res.blob();
        const fd = new FormData();
        fd.append('file', blob, `img-${Date.now()}.png`);
        const r = await fetchWithTimeout(`${config.url.replace(/\/$/, '')}/wp-json/wp/v2/media`, {
            method: 'POST',
            headers: { 'Authorization': `Basic ${auth}` },
            body: fd
        }, useProxy);
        return await r.json();
    };

    const mediaUrls: string[] = [];
    for (const img of imagesBase64.slice(0, 3)) {
        try {
            const m = await uploadMedia(img);
            mediaUrls.push(m.source_url);
        } catch (e) {}
    }

    let content = '';
    sections.forEach((s, idx) => {
        if (s.heading) content += `<h2>${s.heading}</h2>`;
        content += `<p>${s.body}</p>`;
        if (mediaUrls[idx]) content += `<img src="${mediaUrls[idx]}" />`;
    });

    if (tags) content += `<p>Теги: ${tags.replace(/#/g, '')}</p>`;

    const wpDate = formatDateForWP(publishDateStr || "");
    const body: any = { title, content, status: wpDate ? 'future' : 'publish', excerpt: metaDescription };
    if (wpDate) body.date = wpDate;

    const r = await fetchWithTimeout(`${config.url.replace(/\/$/, '')}/wp-json/wp/v2/posts`, {
        method: 'POST',
        headers: { 'Authorization': `Basic ${auth}`, 'Content-Type': 'application/json' },
        body: JSON.stringify(body)
    }, useProxy);
    return await r.json();
};

import { GoogleGenAI, Type } from "@google/genai";
import { DigestData, GeneratedContentPack, NewsItem } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const getDateRange = () => {
  const now = new Date();
  const cutoff = new Date(Date.now() - 48 * 3600000);

  const formatDate = (d: Date) => d.toISOString().split('T')[0];

  return {
    after: formatDate(cutoff),
    before: formatDate(now),
    todayStr: now.toLocaleDateString('ru-RU', { day: 'numeric', month: 'long', year: 'numeric' })
  };
};

export const fetchRealNews = async (count: number = 12): Promise<DigestData> => {
  const model = "gemini-3-flash-preview"; 
  const { after, before, todayStr } = getDateRange();

  const systemInstruction = `
    ТЫ — ГЛАВНЫЙ АНАЛИТИК "ПЕРВОГО ТУРИСТИЧЕСКОГО". 
    СЕГОДНЯ: ${todayStr}. ТЕКУЩИЙ ГОД: 2025.

    ЗАДАЧА: Найти новости, опубликованные СТРОГО с ${after} по ${before}. 

    ЖЕСТКИЕ ПРАВИЛА ВАЛИДАЦИИ:
    1. 2025 ГОД — ЭТО АКТУАЛЬНО. 2024 ГОД — ЭТО МУСОР. Если в тексте новости есть "2024" — не бери её.
    2. ПРОВЕРЯЙ ДАТУ: Нам нужны события вчерашнего и сегодняшнего дня (март 2025). 
    3. ССЫЛКИ: Бери ТОЛЬКО реальные sourceUrl из результатов поиска. Если ссылки нет — новость пропускаем. 
    4. СТИЛЬ: Дайджест и бегущая строка должны быть острыми, ироничными, с эмодзи.
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      // Используем точные операторы даты в поисковом запросе
      contents: `Найди новости туризма РФ и мира after:${after} before:${before}. Исключи любые старые новости за 2024 год. Пример хорошей новости: открытие терминала в марте 2025.`,
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            news: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  summary: { type: Type.STRING },
                  ticker: { type: Type.STRING },
                  date: { type: Type.STRING },
                  location: { type: Type.STRING },
                  sourceUrl: { type: Type.STRING }
                },
                required: ["title", "summary", "ticker", "sourceUrl", "date"]
              }
            },
            formattedDigestText: { type: Type.STRING },
            formattedShortDigest: { type: Type.STRING },
            collagePrompt: { type: Type.STRING }
          },
          required: ["news", "formattedDigestText", "formattedShortDigest", "collagePrompt"]
        }
      }
    });

    const data = JSON.parse(response.text || "{}");

    // Программная фильтрация: убираем всё, где затесался 2024 год
    const cleanNews = (data.news || []).filter((n: any) => {
        const text = (n.title + n.summary + n.date).toLowerCase();
        return !text.includes('2024');
    });

    return {
      ...data,
      news: cleanNews.map((n: any, i: number) => ({ ...n, id: `news-${Date.now()}-${i}` }))
    };
  } catch (error: any) {
    throw new Error(`Ошибка поиска: ${error.message}`);
  }
};

