import { PublishingConfig, WordPressConfig } from "../types";

const SMMBOX_BASE_URL = "https://smmbox.com/api/v1";

const formatDateForWP = (dateStr: string) => {
    if (!dateStr) return null;
    return new Date(dateStr).toISOString().split('.')[0]; 
};

const wrapUrl = (url: string, useProxy: boolean) => {
    return useProxy ? `https://corsproxy.io/?${encodeURIComponent(url)}` : url;
};

const fetchWithTimeout = async (url: string, options: RequestInit = {}, useProxy: boolean = false) => {
    const finalUrl = wrapUrl(url, useProxy);
    const response = await fetch(finalUrl, options);
    if (!response.ok) {
        const errorText = await response.text();
        throw new Error(`API Error (${response.status}): ${errorText || 'Unknown'}`);
    }
    return response;
};

export const fetchSmmBoxGroups = async (config: PublishingConfig) => {
    const url = `${SMMBOX_BASE_URL}/groups`;
    const response = await fetchWithTimeout(url, {
        method: 'GET',
        headers: { 'Authorization': `Bearer ${config.smmBoxToken}` }
    }, config.useProxy);
    const data = await response.json();
    return data.response || [];
};

export const publishToSmmBox = async (config: PublishingConfig, text: string, imagesBase64: string[] = [], publishDate?: Date) => {
    if (!config.smmBoxToken) throw new Error("Токен SmmBox не настроен");
    const allGroups = await fetchSmmBoxGroups(config);
    const groups = allGroups.filter((g: any) => g.name.toLowerCase().includes(config.targetGroupName.toLowerCase()));
    if (groups.length === 0) throw new Error(`Группа "${config.targetGroupName}" не найдена в SmmBox.`);

    // Элементы поста
    const attachments: any[] = [{ type: 'text', text }];
    imagesBase64.slice(0, 3).forEach(img => {
        if (img?.startsWith('data:')) attachments.push({ type: 'photo', original: img });
    });

    // Исправленный эндпоинт /post вместо /posts (что часто вызывает 404)
    const url = `${SMMBOX_BASE_URL}/post`;
    const results = [];

    for (const group of groups) {
        const body: any = {
            group: { id: group.id, social: group.social, type: group.type },
            attachments: attachments,
            options: ['from_group']
        };

        // Отложенный постинг через API SmmBox
        if (publishDate) {
            body.date = Math.floor(publishDate.getTime() / 1000);
        }

        const response = await fetchWithTimeout(url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${config.smmBoxToken}` },
            body: JSON.stringify(body)
        }, config.useProxy);
        results.push(await response.json());
    }
    return results;
};

export const publishToWordPress = async (
    config: WordPressConfig, 
    useProxy: boolean,
    title: string, 
    sections: {heading: string, body: string}[], 
    imagesBase64: string[], 
    tags: string,
    metaDescription: string,
    publishDateStr?: string,
    onProgress?: (msg: string) => void
) => {
    const auth = btoa(`${config.username}:${config.applicationPassword}`);

    const uploadMedia = async (base64: string) => {
        const res = await fetch(base64);
        const blob = await res.blob();
        const fd = new FormData();
        fd.append('file', blob, `tour-img-${Date.now()}.png`);
        const r = await fetchWithTimeout(`${config.url.replace(/\/$/, '')}/wp-json/wp/v2/media`, {
            method: 'POST',
            headers: { 'Authorization': `Basic ${auth}` },
            body: fd
        }, useProxy);
        return await r.json();
    };

    const mediaUrls: string[] = [];
    for (const img of imagesBase64.slice(0, 3)) {
        try {
            const m = await uploadMedia(img);
            mediaUrls.push(m.source_url);
        } catch (e) { console.warn("Media upload failed", e); }
    }

    let content = '';
    sections.forEach((s, idx) => {
        if (s.heading) content += `<h2 class="wp-block-heading"><strong>${s.heading}</strong></h2>`;
        content += `<p>${s.body}</p>`;
        if (mediaUrls[idx]) content += `<figure class="wp-block-image size-large"><img src="${mediaUrls[idx]}" alt="${title}" /></figure>`;
    });

    // В WordPress теги идут без #
    if (tags) {
        content += `<hr /><p><strong>Теги:</strong> ${tags.replace(/#/g, '')}</p>`;
    }

    const wpDate = formatDateForWP(publishDateStr || "");
    const body: any = { 
        title, 
        content, 
        status: wpDate ? 'future' : 'publish', 
        excerpt: metaDescription 
    };
    if (wpDate) body.date = wpDate;

    const r = await fetchWithTimeout(`${config.url.replace(/\/$/, '')}/wp-json/wp/v2/posts`, {
        method: 'POST',
        headers: { 'Authorization': `Basic ${auth}`, 'Content-Type': 'application/json' },
        body: JSON.stringify(body)
    }, useProxy);
    return await r.json();
};

