import { GoogleGenAI, Type } from "@google/genai";
import { DigestData, GeneratedContentPack, NewsItem } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const getDateRange = () => {
  const now = new Date(); 
  const cutoff = new Date(now.getTime() - 48 * 3600000);

  const formatDate = (d: Date) => d.toISOString().split('T')[0];

  return {
    after: formatDate(cutoff),
    before: formatDate(now),
    todayStr: now.toLocaleDateString('ru-RU', { day: 'numeric', month: 'long', year: 'numeric' }),
    currentYear: now.getFullYear()
  };
};

export const fetchRealNews = async (count: number = 15): Promise<DigestData> => {
  const model = "gemini-3-flash-preview"; 
  const { after, before, todayStr, currentYear } = getDateRange();

  const systemInstruction = `
    ТЫ — ПРОФЕССИОНАЛЬНЫЙ АГРЕГАТОР НОВОСТЕЙ ТУРИЗМА.
    СЕГОДНЯ: ${todayStr}. ТЕКУЩИЙ ГОД: ${currentYear}.

    ЗАДАЧА:
    1. Найти минимум 10-15 новостей туризма, опубликованных за последние 48 часов.
    2. ПРИОРИТЕТ РФ: Минимум 10 новостей должны быть про Россию, российских туристов или поездки россиян за рубеж.
    3. ТОЧНОСТЬ ТЕКСТА: Не переписывай и не меняй заголовок и описание новости! Давай их ровно в том виде, в котором они указаны в источнике. Рерайтинг запрещен на этом этапе.
    4. ТОЧНОСТЬ ССЫЛОК: Бери только рабочие URL из результатов поиска. Проверяй, чтобы sourceUrl был на конкретную статью.

    ФОРМАТ ОБЪЕКТА НОВОСТИ:
    - title: Оригинальный заголовок из источника.
    - summary: Оригинальный лид или краткое описание из источника.
    - sourceName: Название издания (например, ТАСС, Вестник АТОР, РБК).
    - date: Дата публикации.
    - sourceUrl: Прямая ссылка на статью.
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Найди последние новости туризма в России и мире (after:${after}). Фокус на российских туристах. Сохраняй оригинальный текст источников.`,
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            news: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  summary: { type: Type.STRING },
                  sourceName: { type: Type.STRING },
                  date: { type: Type.STRING },
                  location: { type: Type.STRING },
                  sourceUrl: { type: Type.STRING },
                  ticker: { type: Type.STRING }
                },
                required: ["title", "summary", "sourceName", "sourceUrl", "date"]
              }
            },
            formattedDigestText: { type: Type.STRING },
            formattedShortDigest: { type: Type.STRING },
            collagePrompt: { type: Type.STRING }
          },
          required: ["news", "formattedDigestText", "formattedShortDigest", "collagePrompt"]
        }
      }
    });

    const data = JSON.parse(response.text || "{}");

    // Оставляем только те новости, которые не старше 48 часов по смыслу и имеют валидный URL
    const cleanNews = (data.news || []).filter((n: any) => {
        return n.sourceUrl && n.sourceUrl.startsWith('http') && n.sourceUrl.length > 15;
    });

    return {
      ...data,
      news: cleanNews.map((n: any, i: number) => ({ ...n, id: `news-${Date.now()}-${i}` }))
    };
  } catch (error: any) {
    throw new Error(`Ошибка поиска новостей: ${error.message}`);
  }
};

export const generateArticleLongread = async (newsItem: NewsItem): Promise<Omit<GeneratedContentPack, 'generatedImages'>> => {
  const model = "gemini-3-pro-preview";
  const systemInstruction = `
    ТЫ — ОСТРОУМНЫЙ РЕДАКТОР КАНАЛА "ПЕРВЫЙ ТУРИСТИЧЕСКИЙ".
    ТВОЯ ЗАДАЧА: Взять сухой факт и превратить его в увлекательный лонгрид.

    СТИЛЬ: Ирония, профессиональная аналитика, "Мы" (Редакция).
    БЕЗ Markdown. Запрещены двойные звездочки (**).

    ПРАВИЛА:
    1. Перепиши новость: ${newsItem.title}. 
    2. Хештеги для сайта: через запятую, без знака #.
    3. Хештеги для соцсетей: в конце текста, обязательно с символом #.
    4. В конце статьи: "Источник: ${newsItem.sourceName} (${newsItem.sourceUrl})".
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Напиши лонгрид и посты. Оригинальная новость от ${newsItem.sourceName}: ${newsItem.title}. Суть: ${newsItem.summary}. Ссылка: ${newsItem.sourceUrl}.`,
      config: { 
        systemInstruction, 
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            siteArticle: {
              type: Type.OBJECT,
              properties: {
                headline: { type: Type.STRING },
                sections: {
                  type: Type.ARRAY,
                  items: {
                    type: Type.OBJECT,
                    properties: { heading: { type: Type.STRING }, body: { type: Type.STRING } },
                    required: ["heading", "body"]
                  }
                },
                hashtags: { type: Type.STRING }
              }
            },
            socials: {
              type: Type.OBJECT,
              properties: { tg: { type: Type.STRING }, vk_ok: { type: Type.STRING } }
            },
            imagePrompts: { type: Type.ARRAY, items: { type: Type.STRING } },
            metaDescription: { type: Type.STRING }
          },
          required: ["siteArticle", "socials", "imagePrompts", "metaDescription"]
        }
      }
    });
    return JSON.parse(response.text || "{}");
  } catch (error) {
    throw new Error("Ошибка генерации контента.");
  }
};

export const generateImageWithFeedback = async (prompt: string): Promise<{ data?: string, error?: string }> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: `${prompt}. Photography style, sharp, travel concept.` }] },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });
    const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    return part?.inlineData?.data ? { data: `data:image/png;base64,${part.inlineData.data}` } : { error: "Ошибка фото" };
  } catch (error: any) { return { error: error.message }; }
};

export const generateImagesForArticle = async (prompts: string[]): Promise<string[]> => {
  const images: string[] = [];
  for (const p of prompts.slice(0, 3)) {
    const res = await generateImageWithFeedback(p);
    if (res.data) images.push(res.data);
    await new Promise(r => setTimeout(r, 600));
  }
  return images;
};

