const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const getDateRange = () => {
  const now = new Date(); 
  const cutoff = new Date(now.getTime() - 48 * 3600000);
  const formatDate = (d: Date) => d.toISOString().split('T')[0];

  return {
    after: formatDate(cutoff),
    before: formatDate(now),
    todayStr: now.toLocaleDateString('ru-RU', { day: 'numeric', month: 'long', year: 'numeric' })
  };
};

export const fetchRealNews = async (count: number = 12): Promise<DigestData> => {
  const model = "gemini-3-flash-preview"; 
  const { after, todayStr } = getDateRange();

  const systemInstruction = `
    ТЫ — ГЛАВНЫЙ РЕДАКТОР ТЕЛЕКАНАЛА "ПЕРВЫЙ ТУРИСТИЧЕСКИЙ".
