                  date: { type: Type.STRING }
                },
                required: ["title", "summary", "sourceName", "sourceUrl"]
              }
            },
            formattedDigestText: { type: Type.STRING },
            formattedShortDigest: { type: Type.STRING },
            collagePrompt: { type: Type.STRING }
          },
          required: ["news", "formattedDigestText", "formattedShortDigest", "collagePrompt"]
        }
      }
    });

    const data = JSON.parse(response.text || "{}");
    return {
      ...data,
      news: (data.news || []).map((n: any, i: number) => ({ 
        ...n, 
        id: `news-${Date.now()}-${i}`,
        ticker: n.title 
      }))
    };
  } catch (error: any) {
    throw new Error(`Ошибка поиска: ${error.message}`);
  }
};

