};

export const generateSingleImage = async (prompt: string): Promise<string> => {
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: { parts: [{ text: `STRICTLY PHOTO-REALISTIC photography of: ${prompt}. Cinematic lighting, high resolution, 8k, travel documentary style. NO DRAWINGS, NO ART, NO COLLAGE, NO CARICATURES, NO ILLUSTRATIONS.` }] },
    config: { imageConfig: { aspectRatio: "16:9" } }
  });
  const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
  if (!part?.inlineData?.data) throw new Error("Не удалось получить изображение");
  return `data:image/png;base64,${part.inlineData.data}`;
};

import { PublishingConfig, WordPressConfig } from "../types";

const SMMBOX_BASE_URL = "https://smmbox.com/api/v1";

const formatDateForWP = (dateStr: string) => {
    if (!dateStr) return null;
    return new Date(dateStr).toISOString().split('.')[0]; 
};

const wrapUrl = (url: string, useProxy: boolean) => {
    return useProxy ? `https://corsproxy.io/?${encodeURIComponent(url)}` : url;
};

const fetchWithTimeout = async (url: string, options: RequestInit = {}, useProxy: boolean = false) => {
    // ВАЖНО: corsproxy.io на бесплатном плане часто блокирует POST-запросы или определенные типы контента.
    // Для SmmBox мы НЕ используем прокси, так как их API обычно доступен напрямую из браузера.
    const finalUrl = useProxy ? wrapUrl(url, true) : url;
    const response = await fetch(finalUrl, options);
    if (!response.ok) {
        const errorText = await response.text();
        throw new Error(`API Error (${response.status}): ${errorText || 'Unknown'}`);
    }
    return response;
};

export const fetchSmmBoxGroups = async (config: PublishingConfig) => {
    const url = `${SMMBOX_BASE_URL}/groups`;
    // Для SmmBox прокси отключен принудительно, чтобы избежать ошибки 403 от corsproxy.io
    const response = await fetchWithTimeout(url, {
        method: 'GET',
        headers: { 'Authorization': `Bearer ${config.smmBoxToken}` }
    }, false);
    const data = await response.json();
    return data.response || [];
};

export const publishToSmmBox = async (config: PublishingConfig, text: string, imagesBase64: string[] = [], publishDate?: Date) => {
    if (!config.smmBoxToken) throw new Error("Токен SmmBox не настроен");

    // Пытаемся получить группы БЕЗ прокси
    const allGroups = await fetchSmmBoxGroups(config);
    const groups = allGroups.filter((g: any) => g.name.toLowerCase().includes(config.targetGroupName.toLowerCase()));
    if (groups.length === 0) throw new Error(`Группа "${config.targetGroupName}" не найдена в SmmBox.`);

    const attachments: any[] = [{ type: 'text', text }];
    imagesBase64.slice(0, 3).forEach(img => {
        if (img?.startsWith('data:')) attachments.push({ type: 'photo', original: img });
    });

    const url = `${SMMBOX_BASE_URL}/post`;
    const results = [];

    for (const group of groups) {
        const body: any = {
            group: { id: group.id, social: group.social, type: group.type },
            attachments: attachments,
            options: ['from_group']
        };

        if (publishDate) {
            body.date = Math.floor(publishDate.getTime() / 1000);
        }

        // Публикуем напрямую, так как POST через бесплатный прокси заблокирован
        const response = await fetchWithTimeout(url, {
            method: 'POST',
            headers: { 
                'Content-Type': 'application/json', 
                'Authorization': `Bearer ${config.smmBoxToken}` 
            },
            body: JSON.stringify(body)
        }, false);
        results.push(await response.json());
    }
    return results;
};

export const publishToWordPress = async (
    config: WordPressConfig, 
    useProxy: boolean,
    title: string, 
    sections: {heading: string, body: string}[], 
    imagesBase64: string[], 
    tags: string,
    metaDescription: string,
    publishDateStr?: string,
    onProgress?: (msg: string) => void
) => {
    const auth = btoa(`${config.username}:${config.applicationPassword}`);

    const uploadMedia = async (base64: string) => {
        const res = await fetch(base64);
        const blob = await res.blob();
        const fd = new FormData();
        fd.append('file', blob, `tour-img-${Date.now()}.png`);

        // Для WordPress прокси оставляем опциональным, так как WP часто блокирует CORS
        const r = await fetchWithTimeout(`${config.url.replace(/\/$/, '')}/wp-json/wp/v2/media`, {
            method: 'POST',
            headers: { 'Authorization': `Basic ${auth}` },
            body: fd
        }, useProxy);
        return await r.json();
    };

    const mediaUrls: string[] = [];
    for (const img of imagesBase64.slice(0, 3)) {
        try {
            const m = await uploadMedia(img);
            mediaUrls.push(m.source_url);
        } catch (e) { console.warn("Media upload failed", e); }
    }

    let content = '';
    sections.forEach((s, idx) => {
        if (s.heading) content += `<h2 class="wp-block-heading"><strong>${s.heading}</strong></h2>`;
        content += `<p>${s.body}</p>`;
        if (mediaUrls[idx]) content += `<figure class="wp-block-image size-large"><img src="${mediaUrls[idx]}" alt="${title}" /></figure>`;
    });

    if (tags) {
        content += `<hr /><p><strong>Теги:</strong> ${tags.replace(/#/g, '')}</p>`;
    }

    const wpDate = formatDateForWP(publishDateStr || "");
    const body: any = { 
        title, 
        content, 
        status: wpDate ? 'future' : 'publish', 
        excerpt: metaDescription 
    };
    if (wpDate) body.date = wpDate;

    const r = await fetchWithTimeout(`${config.url.replace(/\/$/, '')}/wp-json/wp/v2/posts`, {
        method: 'POST',
        headers: { 'Authorization': `Basic ${auth}`, 'Content-Type': 'application/json' },
        body: JSON.stringify(body)
    }, useProxy);
    return await r.json();
};

import React, { useState, useEffect } from 'react';
import { PublishingConfig } from '../types';

interface SettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  config: PublishingConfig;
  onSave: (config: PublishingConfig) => void;
}

export const SettingsModal: React.FC<SettingsModalProps> = ({ isOpen, onClose, config, onSave }) => {
  const [formData, setFormData] = useState<PublishingConfig>(config);
  const [activeTab, setActiveTab] = useState<'smm' | 'wp'>('smm');

  useEffect(() => {
    setFormData(config);
  }, [config]);

  if (!isOpen) return null;

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>, section?: 'wp') => {
    const { name, value, type, checked } = e.target;
    const val = type === 'checkbox' ? checked : value;

    if (section === 'wp') {
        setFormData(prev => ({ 
            ...prev, 
            wordPress: { ...prev.wordPress, [name]: val } 
        }));
    } else {
        setFormData(prev => ({ ...prev, [name]: val }));
    }
  };

  const handleSave = () => {
    const cleanedData: PublishingConfig = {
        ...formData,
        smmBoxToken: formData.smmBoxToken.trim(),
        targetGroupName: formData.targetGroupName.trim() || 'Первый туристический',
        wordPress: {
            url: formData.wordPress.url.trim(),
            username: formData.wordPress.username.trim(),
            applicationPassword: formData.wordPress.applicationPassword.trim()
        }
    };
    localStorage.setItem('tourgenius_settings', JSON.stringify(cleanedData));
    onSave(cleanedData);
    onClose();
  };

  return (
    <div className="fixed inset-0 bg-brand-dark/80 backdrop-blur-md z-[100] flex items-center justify-center p-4">
      <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-xl overflow-hidden flex flex-col border border-slate-200">

        <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
          <div className="flex gap-4">
            <button onClick={() => setActiveTab('smm')} className={`text-sm font-black uppercase tracking-widest px-4 py-2 rounded-xl transition-all ${activeTab === 'smm' ? 'bg-brand-orange text-white' : 'text-slate-400'}`}>SmmBox</button>
            <button onClick={() => setActiveTab('wp')} className={`text-sm font-black uppercase tracking-widest px-4 py-2 rounded-xl transition-all ${activeTab === 'wp' ? 'bg-brand-orange text-white' : 'text-slate-400'}`}>WordPress</button>
          </div>
          <button onClick={onClose} className="text-slate-300 hover:text-brand-orange text-3xl leading-none transition-colors">&times;</button>
        </div>

        <div className="p-8 space-y-8 max-h-[70vh] overflow-y-auto custom-scrollbar">
          <div className="bg-orange-50/50 p-6 rounded-3xl border border-orange-100 space-y-4">
